<?php $this->layout('_studio'); ?>
<section class="studio-page-head"><div><small>BLOG</small><h2>Categorias</h2><p>Organize os artigos publicados no site.</p></div><div class="actions"><a class="studio-btn" href="<?= url('/studio/blog/home') ?>">Voltar aos artigos</a><a class="studio-btn primary" href="<?= url('/studio/blog/category') ?>"><ion-icon name="add-outline"></ion-icon>Nova categoria</a></div></section>
<section class="studio-panel studio-content-list"><header><div><h2>Lista de categorias</h2><small><?= count($categories) ?> registro(s)</small></div></header><div class="studio-table-wrap"><table class="studio-table studio-content-table"><thead><tr><th>Categoria</th><th>Descrição</th><th>Artigos</th><th class="studio-table-action">Ações</th></tr></thead><tbody><?php if (!$categories): ?><tr><td colspan="4"><div class="studio-empty">Nenhuma categoria cadastrada.</div></td></tr><?php endif; ?><?php foreach ($categories as $item): ?><tr><td><div class="studio-content-item"><span class="studio-content-thumb"><ion-icon name="folder-outline"></ion-icon></span><span><strong><?= htmlspecialchars($item->title) ?></strong><small>/<?= htmlspecialchars($item->uri) ?></small></span></div></td><td><?= htmlspecialchars($item->description) ?></td><td><?= $item->posts()->count() ?></td><td class="studio-table-action"><div class="studio-row-actions"><a href="<?= url('/studio/blog/category/'.$item->id) ?>" title="Editar"><ion-icon name="create-outline"></ion-icon></a><form action="<?= url('/studio/blog/category') ?>" method="post" onsubmit="return confirm('Excluir esta categoria?')"><?= csrf_input() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="category_id" value="<?= $item->id ?>"><button title="Excluir"><ion-icon name="trash-outline"></ion-icon></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
